    18	public record Message(long id, String channel, String to, String subject, String body) {
    19	}
    20	package hotel.messages;
    21	
    22	import java.sql.Connection;
    23	import java.sql.PreparedStatement;
    24	import java.sql.ResultSet;
    25	import java.sql.SQLException;
    26	import java.util.ArrayList;
    27	import java.util.List;
    28	import javax.sql.DataSource;
    29	
    30	/** Every message the inn sent, so the front desk can check what each guest received. */
    31	public final class SentMessages {
    32	
    33	    private final DataSource dataSource;
    34	
    35	    public SentMessages(DataSource dataSource) {
    36	        this.dataSource = dataSource;
    37	    }
    38	
    39	    Message add(String channel, String to, String subject, String body) {
    40	        try (Connection connection = dataSource.getConnection();
    41	                PreparedStatement insert = connection.prepareStatement(
    42	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
    43	            insert.setString(1, channel);
    44	            insert.setString(2, to);
    45	            insert.setString(3, subject);
    46	            insert.setString(4, body);
    47	            try (ResultSet generated = insert.executeQuery()) {
    48	                generated.next();
    49	                return new Message(generated.getLong("id"), channel, to, subject, body);
    50	            }
    51	        } catch (SQLException failure) {
    52	            throw new IllegalStateException("could not keep the message to " + to, failure);
    53	        }
    54	    }
    55	
    56	    public List<Message> all() {
    57	        try (Connection connection = dataSource.getConnection();
    58	                PreparedStatement select = connection.prepareStatement(
    59	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
    60	                ResultSet rows = select.executeQuery()) {
    61	            List<Message> messages = new ArrayList<>();
    62	            while (rows.next()) {
    63	                messages.add(new Message(
    64	                        rows.getLong("id"),
    65	                        rows.getString("channel"),
    66	                        rows.getString("recipient"),
    67	                        rows.getString("subject"),
    68	                        rows.getString("body")));
    69	            }
    70	            return messages;
    71	        } catch (SQLException failure) {
    72	            throw new IllegalStateException("could not read the sent messages", failure);
    73	        }
    74	    }
    75	}

