317	                || status == ReservationStatus.CHECKED_OUT;
318	    }
319	
320	    /** The money the inn keeps from this reservation. */
321	    public BigDecimal amountKept() {
322	        return refund == null ? amountPaid : amountPaid.subtract(refund);
323	    }
324	
325	    void changeStatus(ReservationStatus newStatus) {
326	        this.status = newStatus;
327	    }
328	
329	    void confirmPayment() {
330	        this.status = ReservationStatus.CONFIRMED;
331	        this.amountPaid = price.total();
332	    }
333	
334	    void cancel(BigDecimal refundAmount) {
335	        this.status = ReservationStatus.CANCELLED;
336	        this.refund = refundAmount;
337	    }
