347	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
348	public record ReservationReceipt(
349	        String title,
350	        long reservationId,
351	        String guestName,
352	        String guestCpf,
353	        int roomNumber,
354	        RoomType roomType,
355	        LocalDate checkIn,
356	        LocalDate checkOut,
357	        int nights,
358	        BigDecimal subtotal,
359	        BigDecimal discount,
360	        BigDecimal total) {
361	
362	    public ReservationReceipt(Reservation reservation, Room room) {
363	        this(
364	                "Comprovante de reserva",
365	                reservation.id(),
366	                reservation.guest().name(),
367	                reservation.guest().cpf(),
368	                room.number(),
369	                room.type(),
370	                reservation.checkIn(),
371	                reservation.checkOut(),
372	                reservation.price().nights(),
373	                reservation.price().subtotal(),
374	                reservation.price().discount(),
375	                reservation.price().total());
376	    }
377	
378	    public String text() {
379	        StringBuilder text = new StringBuilder();
380	        text.append(title).append(" nº ").append(reservationId).append('\n');
381	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
382	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
383	        text.append("Entrada: ").append(TextFormat.date(checkIn))
384	                .append(" | Saída: ").append(TextFormat.date(checkOut))
385	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
386	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
387	        if (discount.signum() > 0) {
388	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
389	        }
390	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
391	        return text.toString();
392	    }
393	}

